-- Owner-authorised PWD one-on-one options, 30 October 2026. VUV prices are local overrides.
-- Curriculum follows BuildProfitAI, with explicit coding/WordPress and owner-set mentorship periods.
BEGIN;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pwd_lms_courses WHERE slug='full-ai-business-program') AND EXISTS(
 SELECT 1 FROM pwd_lms_orders o JOIN pwd_lms_courses c ON c.id=o.course_id WHERE c.slug IN('how-to-start-a-profitable-business','one-on-one-mentorship')) THEN
 RAISE EXCEPTION 'Legacy enrolments appeared: preserve their offer before replacing the unbooked programmes'; END IF;
 IF EXISTS(SELECT 1 FROM pwd_lms_courses WHERE slug IN('how-to-start-a-profitable-business','one-on-one-mentorship') AND currency<>'VUV') THEN RAISE EXCEPTION 'Unexpected currency/project'; END IF;
END $$;
INSERT INTO pwd_lms_courses(slug,title,description,introduction,kind,amount,currency,published,enrollment_open,private_sessions,is_private,requires_approval)
VALUES ('how-to-start-a-profitable-business','Business Creation & Digital Foundations — One-on-One','18 private 90-minute lessons over 6 weeks, three times a week. Then 1 month of follow-up mentorship. Build your business, from idea to launch.','Welcome to Business Creation & Digital Foundations — One-on-One. VUV 150,000 is the one-time fee for 18 scheduled one-on-one lessons (27 teaching hours) over 6 weeks, followed by 1 month of mentorship. Meet Steve three times a week for 90-minute lessons, with practice between sessions. Afterwards, mentorship is project guidance, review and troubleshooting: meet about once a week or arrange help when needed during the included period. Meetings are arranged together. Your assigned session notes and private recordings are available in your own course space. Domains, hosting, advertising and external subscriptions are separate. No income or sales results are guaranteed.','live',150000,'VUV',true,true,true,false,false),
('one-on-one-mentorship','AI, Coding & Software Development — One-on-One','18 private 90-minute lessons over 6 weeks, three times a week. Then 3 months of follow-up mentorship. Build the tools your business needs.','Welcome to AI, Coding & Software Development — One-on-One. VUV 250,000 is the one-time fee for 18 scheduled one-on-one lessons (27 teaching hours) over 6 weeks, followed by 3 months of mentorship. Meet Steve three times a week for 90-minute lessons, with practice between sessions. Afterwards, mentorship is project guidance, review and troubleshooting: meet about once a week or arrange help when needed during the included period. Meetings are arranged together. Your assigned session notes and private recordings are available in your own course space. Domains, hosting, advertising and external subscriptions are separate. Includes three free months of Digi Assist AI Pro; continued use after that requires a paid subscription. No income or sales results are guaranteed.','live',250000,'VUV',true,true,true,false,false),
('full-ai-business-program','Complete Business & AI Programme — Both Phases','36 private 90-minute lessons over 12 weeks, three times a week. Then 3 months of follow-up mentorship after both phases. Create your business. Then build with AI.','Welcome to Complete Business & AI Programme — Both Phases. VUV 350,000 is the one-time fee for 36 scheduled one-on-one lessons (54 teaching hours) over 12 weeks, followed by 3 months of mentorship after both phases. Meet Steve three times a week for 90-minute lessons, with practice between sessions. Afterwards, mentorship is project guidance, review and troubleshooting: meet about once a week or arrange help when needed during the included period. Meetings are arranged together. Your assigned session notes and private recordings are available in your own course space. Domains, hosting, advertising and external subscriptions are separate. Includes three free months of Digi Assist AI Pro; continued use after that requires a paid subscription. No income or sales results are guaranteed.','live',350000,'VUV',true,true,true,false,false)
ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,introduction=excluded.introduction,kind=excluded.kind,amount=excluded.amount,currency=excluded.currency,published=true,enrollment_open=true,private_sessions=true,is_private=false,requires_approval=false;
CREATE OR REPLACE FUNCTION public.pwd_lms_mentorship_journey() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
DECLARE course_slug text; plan jsonb;
BEGIN
 SELECT slug INTO course_slug FROM pwd_lms_courses WHERE id=NEW.course_id AND private_sessions;
 IF course_slug IS NULL THEN RETURN NEW; END IF;
 plan := $plans${"how-to-start-a-profitable-business":[{"title":"Business idea and customer validation","body":"Choose a customer problem, interview potential buyers and test demand."},{"title":"Business model, pricing and legal basics","body":"Plan revenue, costs, pricing, registration and local obligations."},{"title":"Brand and business setup","body":"Develop your name, logo and story; plan banking and practical setup."},{"title":"Domains, hosting and professional email","body":"Choose and connect the foundations of your business website."},{"title":"Build your website with AI","body":"Create useful pages, copy and a clear customer journey using AI tools."},{"title":"Website launch, SEO and analytics","body":"Check mobile layouts, search visibility and basic visitor measurement."},{"title":"Social media strategy","body":"Choose channels and plan a useful content calendar."},{"title":"Create content with AI","body":"Create and review practical social, written and visual content."},{"title":"Email marketing and customer follow-up","body":"Build a follow-up process and use analytics to improve it."},{"title":"Affiliate niches and programmes","body":"Select relevant programmes and products suited to your audience."},{"title":"Helpful reviews and clear disclosures","body":"Create honest reviews and comparisons with affiliate disclosures."},{"title":"Referral tracking and conversions","body":"Set up links, measure referrals and improve the customer journey."},{"title":"Facebook and Instagram advertising","body":"Plan targeting, budget and creative around a real offer."},{"title":"AI promotional video production","body":"Plan and produce a useful promotional video with AI tools."},{"title":"Google Ads and search campaigns","body":"Understand search intent, keywords, landing pages and budgets."},{"title":"Retargeting and campaign refinement","body":"Plan retargeting and improve the message and landing-page experience."},{"title":"Launch your campaign","body":"Publish your business campaign and test the customer journey."},{"title":"Business launch capstone and review","body":"Review the live campaign, measure early signals and plan mentorship priorities."}],"one-on-one-mentorship":[{"title":"AI fundamentals and prompting","body":"Use AI safely for research, reasoning, content and business tasks."},{"title":"Practical prompt workflows","body":"Build reusable prompts and review output quality against your goals."},{"title":"Automation mapping and audits","body":"Map business processes and scope an automation audit as a service."},{"title":"Chatbots, bookings and customer enquiries","body":"Design a useful chatbot and connect enquiries or booking workflows."},{"title":"CRM and marketing automation","body":"Organise leads and build practical follow-up and marketing workflows."},{"title":"Invoicing and administrative automation","body":"Automate a focused repeatable business task and review the result."},{"title":"AI-assisted WordPress planning","body":"Plan a WordPress website, pages, plugins and a clear customer journey."},{"title":"Build and improve WordPress with AI","body":"Use AI to build content, layouts and integrations while reviewing quality."},{"title":"AI-assisted coding foundations","body":"Read, adapt and debug code with AI; understand files, versions and errors."},{"title":"No-code and AI application builders","body":"Turn a defined problem into an app prototype using appropriate tools."},{"title":"Databases, APIs and integrations","body":"Connect data, accounts and external services with appropriate access controls."},{"title":"Build your software project","body":"Implement the core workflow of your own AI tool, app or business programme."},{"title":"Testing and debugging","body":"Test the main user journey, fix problems and review security basics."},{"title":"Deployment and software launch","body":"Ship a working project and plan ongoing hosting and maintenance."},{"title":"Pricing, licensing and AI services","body":"Package and price software, automation audits and delivery services."},{"title":"Design AI training for institutions","body":"Create a practical curriculum for a business, government or community audience."},{"title":"Workshop delivery and proposals","body":"Practise facilitation and prepare a clear institutional training proposal."},{"title":"Software and mini-training capstone","body":"Demonstrate your working software project and deliver a short training session."}],"full-ai-business-program":[{"title":"Business idea and customer validation","body":"Choose a customer problem, interview potential buyers and test demand."},{"title":"Business model, pricing and legal basics","body":"Plan revenue, costs, pricing, registration and local obligations."},{"title":"Brand and business setup","body":"Develop your name, logo and story; plan banking and practical setup."},{"title":"Domains, hosting and professional email","body":"Choose and connect the foundations of your business website."},{"title":"Build your website with AI","body":"Create useful pages, copy and a clear customer journey using AI tools."},{"title":"Website launch, SEO and analytics","body":"Check mobile layouts, search visibility and basic visitor measurement."},{"title":"Social media strategy","body":"Choose channels and plan a useful content calendar."},{"title":"Create content with AI","body":"Create and review practical social, written and visual content."},{"title":"Email marketing and customer follow-up","body":"Build a follow-up process and use analytics to improve it."},{"title":"Affiliate niches and programmes","body":"Select relevant programmes and products suited to your audience."},{"title":"Helpful reviews and clear disclosures","body":"Create honest reviews and comparisons with affiliate disclosures."},{"title":"Referral tracking and conversions","body":"Set up links, measure referrals and improve the customer journey."},{"title":"Facebook and Instagram advertising","body":"Plan targeting, budget and creative around a real offer."},{"title":"AI promotional video production","body":"Plan and produce a useful promotional video with AI tools."},{"title":"Google Ads and search campaigns","body":"Understand search intent, keywords, landing pages and budgets."},{"title":"Retargeting and campaign refinement","body":"Plan retargeting and improve the message and landing-page experience."},{"title":"Launch your campaign","body":"Publish your business campaign and test the customer journey."},{"title":"Business launch capstone and review","body":"Review the live campaign, measure early signals and plan mentorship priorities."},{"title":"AI fundamentals and prompting","body":"Use AI safely for research, reasoning, content and business tasks."},{"title":"Practical prompt workflows","body":"Build reusable prompts and review output quality against your goals."},{"title":"Automation mapping and audits","body":"Map business processes and scope an automation audit as a service."},{"title":"Chatbots, bookings and customer enquiries","body":"Design a useful chatbot and connect enquiries or booking workflows."},{"title":"CRM and marketing automation","body":"Organise leads and build practical follow-up and marketing workflows."},{"title":"Invoicing and administrative automation","body":"Automate a focused repeatable business task and review the result."},{"title":"AI-assisted WordPress planning","body":"Plan a WordPress website, pages, plugins and a clear customer journey."},{"title":"Build and improve WordPress with AI","body":"Use AI to build content, layouts and integrations while reviewing quality."},{"title":"AI-assisted coding foundations","body":"Read, adapt and debug code with AI; understand files, versions and errors."},{"title":"No-code and AI application builders","body":"Turn a defined problem into an app prototype using appropriate tools."},{"title":"Databases, APIs and integrations","body":"Connect data, accounts and external services with appropriate access controls."},{"title":"Build your software project","body":"Implement the core workflow of your own AI tool, app or business programme."},{"title":"Testing and debugging","body":"Test the main user journey, fix problems and review security basics."},{"title":"Deployment and software launch","body":"Ship a working project and plan ongoing hosting and maintenance."},{"title":"Pricing, licensing and AI services","body":"Package and price software, automation audits and delivery services."},{"title":"Design AI training for institutions","body":"Create a practical curriculum for a business, government or community audience."},{"title":"Workshop delivery and proposals","body":"Practise facilitation and prepare a clear institutional training proposal."},{"title":"Software and mini-training capstone","body":"Demonstrate your working software project and deliver a short training session."}]}$plans$::jsonb -> course_slug;
 IF plan IS NOT NULL THEN
 INSERT INTO pwd_lms_lessons(course_id,order_id,title,position,content,section_title,published,recordings_published)
 SELECT NEW.course_id,NEW.id,lpad(n::text,2,'0')||' · '||(s->>'title'),n::int,
 (s->>'body')||E'\n\nScheduled private lesson: 90 minutes. Arrange the appointment with Steve. Notes and recordings are published to your own enrolment. Follow-up mentorship is a separate support stage after the scheduled training.',
 'Week '||(((n-1)/3)::int+1)::text,true,false
 FROM jsonb_array_elements(plan) WITH ORDINALITY AS v(s,n);
 ELSE
 INSERT INTO pwd_lms_lessons(course_id,order_id,title,position,content)
 SELECT NEW.course_id,NEW.id,title,position,'Your mentor will arrange your sessions and publish notes and recordings here.' FROM(VALUES(1,'Month 1 · Business foundations & AI'),(2,'Month 2 · Websites, WordPress & ecommerce'),(3,'Month 3 · AI coding, software & launch')) AS r(position,title);
 END IF;
 RETURN NEW;
END $$;
COMMIT;
